#!/usr/bin/env python3
"""Logic check for Test C (Claude's construction, before any handoff).

The evidence is encoded exactly as it must appear in the final PNG. Every car's possible
movement history is enumerated (park times, a 2 am move in place, leaving and coming back),
and a history is kept only if it reproduces the visible evidence: which tracks exist, how
sharp they are, where they lead, and whether the roof carries snow. A car can be the culprit
only if some consistent history has it moving inside the car park at 2 am (inside the snowfall)
and its paint matches the scrape. Also checks that each clue is necessary.
Run: python3 test-c/verify_logic.py
"""
import itertools
import json
import pathlib

HERE = pathlib.Path(__file__).resolve().parent
SNOW = (1.0, 3.0)          # snow fell from 1 am to 3 am
CRASH = 2.0                # crunch heard at 2 am; that car is still in the car park
SCRAPE = "yellow"

# evidence as drawn: bay -> (car colour or None, roof snow?)
BAYS = {1: ("yellow", True), 2: ("red", True), 3: (None, None), 4: ("yellow", False), 5: ("yellow", True)}
# visible tyre tracks: (bay, gate<->bay, look) ; look in {"softened", "sharp"}
TRACKS = {(2, "softened"), (4, "sharp"), (5, "softened")}

# discrete times a car can arrive or move: before snow, during (incl. 2 am), after
T = [0.0, 1.5, 2.0, 2.5, 3.5]


def track_look(t):
    if t < SNOW[0]:
        return None          # buried by later snow
    if t < SNOW[1]:
        return "softened"
    return "sharp"


def histories(bay):
    """Yield (events, roof_snow, tracks) for plausible histories of the car now in `bay`.
    Events: arrive from outside at t; optionally move at 2 am (in place, or out and back in)."""
    for arrive in T:
        # A) arrived and never moved again
        yield {"arrive": arrive, "moved_at_2": False}, roof(arrive), visible({(bay, track_look(arrive))})
        # B) arrived earlier, went out at 2 am (clipping the post), came back at r
        if arrive < CRASH:
            for back in [t for t in T if t > CRASH]:
                tr = {(bay, track_look(arrive)), (bay, track_look(CRASH)), (bay, track_look(back))}
                yield {"arrive": arrive, "out_at": CRASH, "back": back, "moved_at_2": True}, roof(back, driven_through=True), visible(tr)
        # C) arrived earlier, moved at 2 am inside the car park and re-parked in this bay
        if arrive < CRASH:
            tr = {(bay, track_look(arrive)), (bay, track_look(CRASH))}
            yield {"arrive": arrive, "shuffle_at": CRASH, "moved_at_2": True}, roof(arrive), visible(tr)
        # D) arrived at exactly 2 am, clipping the post on the way in
    # (D is covered by A with arrive == 2.0; moved_at_2 then means "was driving at 2 am")


def roof(last_parked, driven_through=False):
    """Snow on the roof iff the car stood still for part of the snowfall after it last parked
    (snow that fell on a car while it was being driven is assumed blown off)."""
    return last_parked < SNOW[1]


def visible(tr):
    return {x for x in tr if x[1] is not None}


def consistent(bay, colour_roof):
    colour, roof_snow = colour_roof
    want = {x for x in TRACKS if x[0] == bay}
    out = []
    for ev, r, tr in histories(bay):
        if r == roof_snow and tr == want:
            ev = dict(ev)
            ev["at_2am_moving"] = ev.get("moved_at_2") or ev["arrive"] == CRASH
            out.append(ev)
    return out


def culprits(use_colour=True, use_tracks=True):
    found = []
    for bay, (colour, roof_snow) in BAYS.items():
        if colour is None:
            continue
        if use_colour and colour != SCRAPE:
            continue
        if not use_tracks:
            found.append(bay)
            continue
        if any(h["at_2am_moving"] for h in consistent(bay, (colour, roof_snow))):
            found.append(bay)
    return found


report = {
    "consistent_histories": {b: consistent(b, BAYS[b]) for b in BAYS if BAYS[b][0]},
    "culprit_all_clues": culprits(),
    "culprit_without_paint_colour": culprits(use_colour=False),
    "culprit_without_track_reading": culprits(use_tracks=False),
}
report["unique"] = report["culprit_all_clues"] == [5]
report["each_clue_necessary"] = len(report["culprit_without_paint_colour"]) > 1 and len(report["culprit_without_track_reading"]) > 1
print(json.dumps(report, indent=1, default=str))
(HERE / "logic-verification.json").write_text(json.dumps(report, indent=1, default=str) + "\n")
print("LOGIC PASS" if report["unique"] and report["each_clue_necessary"] else "LOGIC FAIL")

